Method.Implementation:
 #dim status as %Status
 set status = $$$OK
 $$$TRACE("Inside OnMessage method")	 

 try {		 


	if (..CheckObject() '= $$$OK) {
	 	$$$TRACE("**** Object does not exists ****")
	 	// Try to re intialize
	 	set result = ..OnInit()
		if (result '= $$$OK)
		{
			set status = ##class(IHC.ITF.ITFCOMMON.Utility).DisableMsgError("Out-Cdr-Demogr-Cff-Tux-UPDATE", "UpdateMMI failed. MMI#: " _pRequest.StringValue_ " ; Reason: " _ result)						
			return status
		}
 	}

     $$$TRACE("HL7 Msg:: "_ pRequest.RawContent)	
	 set result = ..objCdrTuxService.updateMMI(pRequest.RawContent)		
	$$$TRACE("Call Response: " _ result)


	if ("1" = result){
		$$$TRACE("Update Sucessful!!! MMI#: " _ pRequest.GetValueAt("PID:PatientID.ID"))
		set pResponse = ##class(Ens.StringResponse).%New("")
	    set pResponse.StringValue = result
	}else{		
		set status = ##class(IHC.ITF.ITFCOMMON.Utility).DisableMsgError("Out-Cdr-Demogr-Cff-Tux-UPDATE", "MMIUpdate failed. MMI#: " _ pRequest.GetValueAt("PID:PatientIdentifierList(1).ID") _ " ; Reason: " _ result)					
	}

 } catch err {	 
 	 Set status = ..ExceptionHandler(err, "OnMessage")
 }  
 return status
